    void recoverTree(TreeNode* root) {
        TreeNode* curr = nullptr;
        TreeNode* prev = nullptr;
        TreeNode* first = nullptr;
        TreeNode* second = nullptr;
        while (root) {
            if (!root->left) {
                // operation
                prev = curr;
                curr = root;
                if (prev && prev->data > curr->data) {
                    if (!first) first = prev;
                    second = curr;
                }
                root = root->right;
            } else {
                TreeNode* temp = root->left;
                while (temp->right && temp->right != root) {
                    temp = temp->right;
                }
                if (!temp->right) {
                    temp->right = root;
                    root = root->left;
                } else {
                    temp->right = nullptr;
                    // operation
                    prev = curr;
                    curr = root;
                    if (prev && prev->data > curr->data) {
                        if (!first) first = prev;
                        second = curr;
                    }
                    root = root->right;
                }
            }
        }
        swap(first->data, second->data);
    }
};
```

## Complexity
**Time Complexity:** 
O(n) where n is the number of nodes in the tree, as the Morris Traversal visits each node at most three times during the thread creation and traversal process

**Space Complexity:**
O(1) because the algorithm uses only a constant amount of extra pointers regardless of the input tree structure
